// 这是注释
/* 这是多行注释 */

// 弹窗输出
alert('Hello, World!');

// 控制台输出（推荐调试用）
console.log('你好，世界！');
console.log('我在学习JavaScript！');

// 写入页面
document.write('<h1>欢迎来到JS世界</h1>');

// 输入框
let name = prompt('请输入你的名字：');
alert('你好，' + name + '！');

// 变量声明
let name = '小明';
let age = 14;
const PI = 3.14159; // 常量，不能改

// 输出
console.log('姓名：', name);
console.log('年龄：', age);

// 数据类型
console.log(typeof 123);       // number
console.log(typeof 'hello');   // string
console.log(typeof true);      // boolean
console.log(typeof undefined); // undefined
console.log(typeof null);      // object（历史遗留bug）

// 模板字符串（反引号，和Python的f-string类似）
let msg = `我叫${name}，今年${age}岁`;
console.log(msg);

// == 和 === 的区别
console.log(1 == '1');   // true（自动转类型了！坑！）
console.log(1 === '1');  // false（类型不同，推荐用===）

// 条件判断
let score = 85;
if (score >= 90) {
  console.log('优秀');
} else if (score >= 80) {
  console.log('良好');
} else if (score >= 60) {
  console.log('及格');
} else {
  console.log('不及格');
}

// 三目运算符（和Python类似）
let age = 20;
let status = age >= 18 ? '成年' : '未成年';
console.log(status);

// 获取用户输入
// let num = prompt('请输入一个数字：');
// num = parseInt(num); // 转成整数
// console.log('你输入的是：', num);

// for循环
for (let i = 1; i <= 5; i++) {
  console.log('第' + i + '次循环');
}

// 计算1到100的和
let sum = 0;
for (let i = 1; i <= 100; i++) {
  sum += i;
}
console.log('1到100的和：', sum);

// while循环
let i = 1;
while (i <= 5) {
  console.log('while: ' + i);
  i++;
}

// for...of遍历数组
let fruits = ['苹果', '香蕉', '橘子'];
for (let fruit of fruits) {
  console.log('我喜欢' + fruit);
}

// 九九乘法表
for (let i = 1; i <= 9; i++) {
  let line = '';
  for (let j = 1; j <= i; j++) {
    line += `${j}x${i}=${i*j}\t`;
  }
  console.log(line);
}

// 函数声明
function sayHello(name) {
  console.log('你好，' + name + '！');
}

// 调用函数
sayHello('小明');
sayHello('小红');

// 带返回值的函数
function add(a, b) {
  return a + b;
}

let result = add(3, 5);
console.log('3 + 5 =', result);

// 函数表达式
const multiply = function(a, b) {
  return a * b;
};
console.log(multiply(4, 5));

// 箭头函数（ES6，更简洁）
const subtract = (a, b) => a - b;
console.log(subtract(10, 3));

// 没有返回值的函数，默认返回undefined
function noReturn() {
  console.log('这个函数没有return');
}
console.log(noReturn()); // undefined

// 默认参数
function greet(name = '陌生人', greeting = '你好') {
  console.log(greeting + '，' + name + '！');
}

greet(); // 你好，陌生人！
greet('小明'); // 你好，小明！
greet('小红', '早上好'); // 早上好，小红！

// 剩余参数 ...rest
function sum(...nums) {
  let total = 0;
  for (let n of nums) {
    total += n;
  }
  return total;
}

console.log(sum(1, 2, 3)); // 6
console.log(sum(1, 2, 3, 4, 5)); // 15

// arguments对象（老方式）
function oldSum() {
  let total = 0;
  for (let i = 0; i < arguments.length; i++) {
    total += arguments[i];
  }
  return total;
}

// 全局变量
let globalVar = '我是全局的';

function test() {
  // 函数内的变量，外面访问不到
  let localVar = '我是局部的';
  console.log(globalVar); // 能访问全局的
  console.log(localVar);  // 能访问局部的

  if (true) {
    let blockVar = '我是块级的';
    var notBlockVar = '我是var，不是块级的'; // var没有块级作用域
  }
  // console.log(blockVar); // 报错，访问不到（let有块级作用域）
  console.log(notBlockVar); // 能访问到（var没有块级作用域，坑！）
}

test();
console.log(globalVar); // 能访问
// console.log(localVar); // 报错，访问不到函数内部的变量

let nums = [1, 2, 3, 4, 5];

// push/pop
nums.push(6); // 末尾加
console.log(nums); // [1,2,3,4,5,6]
nums.pop(); // 末尾删
console.log(nums); // [1,2,3,4,5]

// forEach 遍历
nums.forEach((item, index) => {
  console.log(`第${index}个：${item}`);
});

// map 映射 - 每个元素处理一下，返回新数组
let doubled = nums.map(n => n * 2);
console.log(doubled); // [2,4,6,8,10]

// filter 过滤 - 留下满足条件的
let evens = nums.filter(n => n % 2 === 0);
console.log(evens); // [2,4]

// reduce 归并 - 把所有元素归并成一个值
let sum = nums.reduce((acc, cur) => acc + cur, 0);
console.log(sum); // 15

// find 查找第一个满足条件的
let found = nums.find(n => n > 3);
console.log(found); // 4

// sort 排序（注意：默认是按字符串排的，数字要传函数）
let arr = [3, 1, 4, 1, 5, 9, 2, 6];
arr.sort((a, b) => a - b); // 升序
console.log(arr); // [1,1,2,3,4,5,6,9]

// 创建对象
let person = {
  name: '小明',
  age: 14,
  gender: '男',
  hobbies: ['编程', '游戏', '骑车'],
  sayHi: function() {
    console.log('大家好，我叫' + this.name);
  }
};

// 访问属性
console.log(person.name);   // 小明
console.log(person.age);    // 14
console.log(person['gender']); // 男

// 修改属性
person.age = 15;
person.school = '汇文中学'; // 添加新属性
delete person.gender;       // 删除属性

// 调用方法
person.sayHi();

// 遍历对象
for (let key in person) {
  console.log(key + ': ' + person[key]);
}

// Object.keys/values/entries
console.log(Object.keys(person));   // 所有键
console.log(Object.values(person)); // 所有值
console.log(Object.entries(person)); // 所有键值对数组

// 解构赋值（ES6特色，超好用！）
let { name, age } = person;
console.log(name, age); // 小明 15

// 展开运算符 ...
let obj1 = { a: 1, b: 2 };
let obj2 = { ...obj1, c: 3 }; // 复制并添加
console.log(obj2); // {a:1, b:2, c:3}

let str = 'Hello, JavaScript!';

console.log(str.length);          // 18
console.log(str.toUpperCase());   // HELLO, JAVASCRIPT!
console.log(str.toLowerCase());   // hello, javascript!
console.log(str.slice(0, 5));     // Hello
console.log(str.indexOf('Java')); // 7
console.log(str.includes('JS'));  // false
console.log(str.startsWith('He')); // true
console.log(str.endsWith('!'));   // true
console.log(str.replace('Hello', 'Hi')); // Hi, JavaScript!
console.log('哈'.repeat(5));      // 哈哈哈哈哈

// 分割成数组
let dateStr = '2024-01-15';
let parts = dateStr.split('-');
console.log(parts); // ['2024', '01', '15']

// 模板字符串（反引号）
let name = '小明';
let age = 14;
let greeting = `大家好，我叫${name}，今年${age}岁。`;
console.log(greeting);

// 模板字符串还能换行
let poem = `床前明月光，
疑是地上霜。
举头望明月，
低头思故乡。`;
console.log(poem);

// 按id找
let title = document.getElementById('title');

// 按选择器找（第一个匹配的）
let box = document.querySelector('.box'); // 按class
let nav = document.querySelector('#nav'); // 按id
let firstLi = document.querySelector('ul li'); // 按标签+层级
let btn = document.querySelector('button[type="submit"]'); // 属性选择器

// 找所有匹配的
let allItems = document.querySelectorAll('.item');
let allLi = document.querySelectorAll('ul li');

// querySelectorAll返回的是NodeList，可以用forEach遍历
allItems.forEach(item => {
  console.log(item);
});

// 注意：getElementsBy系列返回的是HTMLCollection（动态集合），
// querySelectorAll返回的是NodeList（静态集合），
// 一般用querySelectorAll就够了

let title = document.querySelector('#title');

// 操作内容
title.innerText = '新的标题'; // 设置文本
console.log(title.innerText);  // 获取文本

title.innerHTML = '<em>带样式的</em>标题'; // 会解析HTML标签

// 操作属性
let img = document.querySelector('img');
img.src = 'new-pic.jpg';      // 修改图片地址
img.alt = '新的描述';

console.log(img.getAttribute('src')); // 也可以这样获取
img.setAttribute('title', '鼠标悬停提示'); // 设置属性

// class操作（推荐用classList）
let box = document.querySelector('.box');
box.classList.add('active');   // 添加类
box.classList.remove('old');   // 删除类
box.classList.toggle('show');  // 切换（有就删，没有就加）
console.log(box.classList.contains('active')); // 是否有某个类

let box = document.querySelector('.box');

// 设置行内样式
box.style.width = '200px';
box.style.height = '100px';
box.style.backgroundColor = '#6366f1';
box.style.color = 'white';
box.style.fontSize = '20px';
box.style.borderRadius = '10px';

// 获取样式（行内的才能用style取到）
console.log(box.style.width); // 200px

// 获取计算后的样式（最终生效的，包括CSS文件里的）
let style = getComputedStyle(box);
console.log(style.padding); // 即使没在行内写，也能取到

// 推荐：改样式用CSS类，JS只加/减类
box.classList.add('big-red'); // 这样样式都在CSS里，好维护

// 获取元素
let btn = document.querySelector('#myBtn');
let box = document.querySelector('.box');

// 方式1：DOM0级（简单，但一个事件只能绑一个函数）
btn.onclick = function() {
  alert('你点击了按钮！');
};

// 方式2：addEventListener（推荐！）
btn.addEventListener('click', function() {
  console.log('点击了按钮');
  box.style.backgroundColor = 'red';
});

// 可以绑定多个处理函数
btn.addEventListener('click', function() {
  console.log('第二个处理函数也执行了');
});

// 鼠标移入移出
box.addEventListener('mouseover', function() {
  box.style.transform = 'scale(1.1)';
});
box.addEventListener('mouseout', function() {
  box.style.transform = 'scale(1)';
});

// 移除事件监听（注意：必须是同一个函数引用）
function handleClick() {
  console.log('click');
}
btn.addEventListener('click', handleClick);
// btn.removeEventListener('click', handleClick); // 移除

// 点击页面任意位置，显示鼠标坐标
document.addEventListener('click', function(e) {
  console.log(`鼠标位置：(${e.clientX}, ${e.clientY})`);
  console.log('点击的元素是：', e.target);
});

// 键盘事件
document.addEventListener('keydown', function(e) {
  console.log('按下了：', e.key);
  console.log('键码：', e.keyCode);
  if (e.key === 'Escape') {
    console.log('你按了ESC键');
  }
});

// 阻止默认行为
let link = document.querySelector('a');
link.addEventListener('click', function(e) {
  e.preventDefault(); // 阻止链接跳转
  alert('链接被拦截了！');
});

// 表单提交时阻止默认跳转
let form = document.querySelector('form');
form.addEventListener('submit', function(e) {
  e.preventDefault();
  console.log('表单被提交了，但不会跳转页面');
  // 这里可以用AJAX发送数据
});

// 创建新元素
let newDiv = document.createElement('div');
newDiv.className = 'new-box';
newDiv.innerText = '我是新创建的div';
newDiv.style.color = 'red';

// 添加到页面中
document.body.appendChild(newDiv); // 加到body最后

// 在某个元素前面插入
let ref = document.querySelector('#reference');
let newP = document.createElement('p');
newP.innerText = '插入的段落';
ref.parentNode.insertBefore(newP, ref);

// 删除元素
// 方式1：自己删自己
newDiv.remove();

// 方式2：父元素删子元素
// ref.parentNode.removeChild(ref);

// 更简单的方式：直接用innerHTML（字符串拼接）
let list = document.querySelector('#list');
let html = '';
for (let i = 1; i <= 5; i++) {
  html += `<li>第${i}项</li>`;
}
list.innerHTML = html; // 一次性写入，性能好，代码简洁
